UPDATE courses SET
    course_description = '<div aria-labelledby="course-overview-tab" class="tab-pane fade show active d-block" id="course-overview" role="tabpanel"> <p>This qualification reflects the role of individuals in the accounting and bookkeeping industry, including business activity statement (BAS) agents and contract bookkeepers; and of those employees performing bookkeeping tasks for organisations in a range of industries. It includes preparing and lodging business and instalment activity statements, data processing, monthly reconciliations, preparing budgets, preparing reports on financial performance and the position of the business, preparing end-of-year adjustments, and finalising financial records after year-end.Dealing with the Commissioner of Taxation on behalf of a taxpayer in relation to activity statements and other lodgement matters is also a key component of the role that this qualification reflects. Individuals in these roles apply theoretical and specialist skills and knowledge to work autonomously, and exercise judgement in completing routine and non-routine activities.</p> <div> </div> <strong>Target Groups:<br/></strong> <ul> <li>Individuals seeking to pursue higher education qualifications.</li> <li>Individuals seeking to pursue a career in the accounting sector.</li> <li>Individuals seeking to enter a new industry sector.</li> </ul> <p><strong><br/>Career Outcome:<br/></strong>Accounts Assistant, payroll clerk, payroll payable or receivable clerk, bookkeeper, or financial clerk.</p> <p><strong><br/>Future Pathways:<br/></strong>Students who complete this course may pursue higher level qualifications within and/or across the accounting and finance sector including FNS50222-Diploma of Accounting or a range of other Diploma qualifications.</p> </div>',
    total_course_duration = 'Up to 78 Weeks',
    offshore_tuition_fee = 22500,
    enrolment_fee = 250,
    materials_fee = 1000,
    entry_requirements = '<div class="details-description"> <p><strong data-end="207" data-start="188">Age Requirement</strong>: </p><ul data-end="286" data-start="209"> <li data-end="286" data-start="209">Applicants must be at least 18 years old at the commencement of the course.</li> </ul> <strong data-end="315" data-start="288"><br/>Academic Qualifications</strong>: <ul data-end="487" data-start="317"> <li data-end="383" data-start="317">Completion of Australian Year 11 or an equivalent qualification.</li> <li data-end="487" data-start="384">For certain courses, completion of an AQF Certificate III or a relevant qualification may be required.</li> </ul> <strong data-end="521" data-start="489"><br/>English Language Proficiency</strong>: <ul data-end="1014" data-start="523"> <li data-end="671" data-start="523">An overall valid academic IELTS score of at least 6.0, with no band less than 5.5, or an equivalent score from a recognized English language test.</li> <li data-end="1014" data-start="672">Alternatively, proficiency can be demonstrated by: <ul data-end="1014" data-start="727"> <li data-end="809" data-start="727">Completion of an Advanced level English course from an approved ELICOS provider.</li> <li data-end="940" data-start="812">Completion of a Certificate IV level course in an Australian Registered Training Organization (RTO) within the last two years.</li> <li data-end="1014" data-start="943">Successfully passing Western Sydney College’s English Placement Test.</li> </ul> </li> </ul> <strong data-end="1043" data-start="1016"><br/>Additional Requirements</strong>: <ul data-end="1262" data-start="1045"> <li data-end="1125" data-start="1045">International students must meet the Student Visa (Subclass 500) requirements.</li> <li data-end="1262" data-start="1126">For packaged courses, students must successfully complete the lower-level qualification to progress to the higher-level qualification.</li> </ul><p></p> </div>',
    apply_form = 'https://wsc.nsw.edu.au/courses/accounting-and-bookkeeping/fns40222-certificate-iv-in-accounting-and-bookkeeping/',
    updated_at = NOW()
WHERE cricos_course_code = '110013B';
UPDATE courses SET
    course_description = '<div aria-labelledby="course-overview-tab" class="tab-pane fade show active d-block" id="course-overview" role="tabpanel"> <p>This qualification reflects accounting job roles in financial services and other industries, including tax agents, accounts payable and accounts receivable officers, payroll service providers, and employees performing a range of accounting tasks for organisations in a range of industries. Individuals in these roles apply solutions to a range of often complex problems, and analyse and evaluate information from a variety of sources. They apply initiative to plan, coordinate and evaluate their own work and provide guidance to others within defined guidelines.</p> <div> </div> <strong>Target Groups:<br/></strong> <ul> <li>Individuals seeking to pursue higher education qualifications.</li> <li>Individuals seeking to pursue a career in the accounting sector.</li> </ul> <p><strong><br/>Career Outcome:<br/></strong>Accounts Assistant, payroll clerk, payroll payable or receivable clerk, bookkeeper, or financial clerk.<strong><br/></strong><strong><br/>Future Pathways:<br/></strong>Students who complete this course may pursue higher level qualifications within and/or across the accounting and finance sector including FNS60222-Advanced Diploma of Accounting or a range of other Diploma qualifications.</p> </div>',
    total_course_duration = 'Up to 65 Weeks',
    offshore_tuition_fee = 18750,
    enrolment_fee = 250,
    materials_fee = 1000,
    entry_requirements = '<div class="details-description"> <p><strong data-end="207" data-start="188">Age Requirement</strong>: </p><ul data-end="286" data-start="209"> <li data-end="286" data-start="209">Applicants must be at least 18 years old at the commencement of the course.</li> </ul> <strong data-end="315" data-start="288"><strong data-end="315" data-start="288"><br/>Academic Qualifications<br/></strong></strong> <p class="" data-end="375" data-start="224">Before commencing this qualification, individuals must have successfully completed the following units of competency (or their recognized equivalents):</p> <ul data-end="728" data-start="377"> <li class="" data-end="455" data-start="377"> <p class="" data-end="455" data-start="379"><strong data-end="392" data-start="379">FNSACC321</strong> – Process financial transactions and extract interim reports</p> </li> <li class="" data-end="518" data-start="456"> <p class="" data-end="518" data-start="458"><strong data-end="471" data-start="458">FNSACC322</strong> – Administer subsidiary accounts and ledgers</p> </li> <li class="" data-end="598" data-start="519"> <p class="" data-end="598" data-start="521"><strong data-end="534" data-start="521">FNSACC418</strong> – Work effectively in the accounting and bookkeeping industry</p> </li> <li class="" data-end="728" data-start="599"> <p class="" data-end="644" data-start="601"><strong data-end="614" data-start="601">FNSACC421</strong> – Prepare financial reports</p> <blockquote data-end="728" data-start="647"> <p class="" data-end="728" data-start="649"><em data-end="728" data-start="649">(This unit is considered equivalent to BSBFIA401 – Prepare financial reports)</em></p> </blockquote> </li> </ul> <p class="" data-end="857" data-start="730">These competencies may have been previously achieved through completion of one of the following programs (or their equivalent):</p> <ul data-end="975" data-start="859"> <li class="" data-end="911" data-start="859"> <p class="" data-end="911" data-start="861"><strong data-end="875" data-start="861">FNSSS00014</strong> – Accounting Principles Skill Set</p> </li> <li class="" data-end="975" data-start="912"> <p class="" data-end="975" data-start="914"><strong data-end="926" data-start="914">FNS40222</strong> – Certificate IV in Accounting and Bookkeeping</p> </li> </ul> <br/><strong data-end="521" data-start="489"><br/>English Language Proficiency</strong>: <ul data-end="1014" data-start="523"> <li data-end="671" data-start="523">An overall valid academic IELTS score of at least 6.0, with no band less than 5.5, or an equivalent score from a recognized English language test.</li> <li data-end="1014" data-start="672">Alternatively, proficiency can be demonstrated by: <ul data-end="1014" data-start="727"> <li data-end="809" data-start="727">Completion of an Advanced level English course from an approved ELICOS provider.</li> <li data-end="940" data-start="812">Completion of a Certificate IV level course in an Australian Registered Training Organization (RTO) within the last two years.</li> <li data-end="1014" data-start="943">Successfully passing Western Sydney College’s English Placement Test.</li> </ul> </li> </ul> <strong data-end="1043" data-start="1016"><br/>Additional Requirements</strong>: <ul data-end="1262" data-start="1045"> <li data-end="1125" data-start="1045">International students must meet the Student Visa (Subclass 500) requirements.</li> <li data-end="1262" data-start="1126">For packaged courses, students must successfully complete the lower-level qualification to progress to the higher-level qualification.</li> </ul><p></p> </div>',
    apply_form = 'https://wsc.nsw.edu.au/courses/accounting-and-bookkeeping/fns50222-diploma-of-accounting/',
    updated_at = NOW()
WHERE cricos_course_code = '111699C';
UPDATE courses SET
    course_description = '<div aria-labelledby="course-overview-tab" class="tab-pane fade show active d-block" id="course-overview" role="tabpanel"> <p>This qualification reflects the role of individuals working in accounting and seeking professional recognition, including tax agents, accounts managers and business analysts; and to employees performing a range of accounts management tasks for organisations in a range of industries. At this level individuals are expected to apply theoretical and technical skills in a range of situations and to display initiative and judgement in planning activities. They have autonomy in performing complex operations and can be responsible for planning, coordinating and evaluating the work of others within broad parameters.</p> <div> </div> <strong>Target Groups:<br/></strong> <ul> <li>Individuals seeking to pursue higher education qualifications.</li> <li>Individuals seeking to pursue a career in the accounting sector as an Accountant, Assistant Accountant, Finance, and Accounting Manager.</li> <li>Individuals seeking to enter a new industry sector.</li> </ul> <p><strong><br/>Career Outcome:<br/></strong>Assistant Accountant, Finance and Accounts Manager or Office Manager, Senior Financial Officers, Account Payable and Receivable Manager.</p> <p><strong>Future Pathways:<br/></strong>Students who complete this course may pursue higher level qualifications within and/or across the accounting and finance sector including Bachelor of<br/>Accounting or a range of other qualifications.</p> </div>',
    total_course_duration = 'Up to 78 Weeks',
    offshore_tuition_fee = 22500,
    enrolment_fee = 250,
    materials_fee = 1000,
    entry_requirements = '<div class="details-description"> <p><strong data-end="207" data-start="188">Age Requirement</strong>: </p><ul data-end="286" data-start="209"> <li data-end="286" data-start="209">Applicants must be at least 18 years old at the commencement of the course.</li> </ul> <strong data-end="315" data-start="288"><strong data-end="315" data-start="288"><br/>Academic Qualifications<br/><br/></strong></strong>To be eligible for entry into this qualification, individuals must have successfully completed one of the following qualifications (or their equivalent): <ul data-end="569" data-start="289"> <li class="" data-end="330" data-start="289"> <p class="" data-end="330" data-start="291"><strong data-end="303" data-start="291">FNS50222</strong> – Diploma of Accounting,</p> </li> <li class="" data-end="398" data-start="331"> <p class="" data-end="398" data-start="333">or the superseded version <strong data-end="371" data-start="359">FNS50217</strong> – Diploma of Accounting,</p> </li> <li class="" data-end="569" data-start="399"> <p class="" data-end="569" data-start="401">or an equivalent qualification, <strong data-end="450" data-start="433">provided that</strong> the elective unit <strong data-end="524" data-start="469">BSBTEC402 – Design and produce complex spreadsheets</strong> (or its equivalent) has also been completed.</p> </li> </ul> <br/><strong data-end="521" data-start="489"><br/>English Language Proficiency</strong>: <ul data-end="1014" data-start="523"> <li data-end="671" data-start="523">An overall valid academic IELTS score of at least 6.0, with no band less than 5.5, or an equivalent score from a recognized English language test.</li> <li data-end="1014" data-start="672">Alternatively, proficiency can be demonstrated by: <ul data-end="1014" data-start="727"> <li data-end="809" data-start="727">Completion of an Advanced level English course from an approved ELICOS provider.</li> <li data-end="940" data-start="812">Completion of a Certificate IV level course in an Australian Registered Training Organization (RTO) within the last two years.</li> <li data-end="1014" data-start="943">Successfully passing Western Sydney College’s English Placement Test.</li> </ul> </li> </ul> <strong data-end="1043" data-start="1016"><br/>Additional Requirements</strong>: <ul data-end="1262" data-start="1045"> <li data-end="1125" data-start="1045">International students must meet the Student Visa (Subclass 500) requirements.</li> <li data-end="1262" data-start="1126">For packaged courses, students must successfully complete the lower-level qualification to progress to the higher-level qualification.</li> </ul><p></p> </div>',
    apply_form = 'https://wsc.nsw.edu.au/courses/accounting-and-bookkeeping/fns60222-advanced-diploma-of-accounting/',
    updated_at = NOW()
WHERE cricos_course_code = '111700D';
UPDATE courses SET
    course_description = '<div aria-labelledby="course-overview-tab" class="tab-pane fade show active d-block" id="course-overview" role="tabpanel"> <p>This qualification provides a trade outcome in painting and decorating for residential and commercial construction work.</p><p><br/></p><p>Occupational titles may include: </p><p><br/></p><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Painter and Decorator.</li></ol><p><br/></p><p>Licensing, legislative and regulatory or certification requirements for painting and decorating work differ between States and Territories. Please consult with the relevant regulatory authority.</p><p>This qualification is suitable for an Australian Apprenticeship pathway.</p><p>Completion of the general construction induction training program, specified in the Safe Work Australia model Code of Practice: Construction Work, is required by anyone carrying out construction work. Achievement of CPCWHS1001 Prepare to work safely in the construction industry meets this requirement.</p><p><br/></p><p>Target Groups:</p><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Individuals seeking to pursue a career as a Painter and Decorator </li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Individuals seeking to enhance their current skills</li></ol><p><br/></p><p>Future Pathways:</p><p>Students who complete this course may wish to continue their education into Certificate IV or Diploma.</p> </div>',
    total_course_duration = 'Up to 104 Weeks',
    offshore_tuition_fee = 30000,
    enrolment_fee = 250,
    materials_fee = 2000,
    entry_requirements = '<div class="details-description"> <p><strong data-end="207" data-start="188">Age Requirement</strong>: </p><ul data-end="286" data-start="209"> <li data-end="286" data-start="209">Applicants must be at least 18 years old at the commencement of the course.</li> </ul> <strong data-end="315" data-start="288"><br/>Academic Qualifications</strong>: <ul data-end="487" data-start="317"> <li data-end="383" data-start="317">Completion of Australian Year 11 or an equivalent qualification.</li> <li data-end="487" data-start="384">For certain courses, completion of an AQF Certificate III or a relevant qualification may be required.</li> </ul> <strong data-end="521" data-start="489"><br/>English Language Proficiency</strong>: <ul data-end="1014" data-start="523"> <li data-end="671" data-start="523">An overall valid academic IELTS score of at least 6.0, with no band less than 5.5, or an equivalent score from a recognized English language test.</li> <li data-end="1014" data-start="672">Alternatively, proficiency can be demonstrated by: <ul data-end="1014" data-start="727"> <li data-end="809" data-start="727">Completion of an Advanced level English course from an approved ELICOS provider.</li> <li data-end="940" data-start="812">Completion of a Certificate IV level course in an Australian Registered Training Organization (RTO) within the last two years.</li> <li data-end="1014" data-start="943">Successfully passing Western Sydney College’s English Placement Test.</li> </ul> </li> </ul> <strong data-end="1043" data-start="1016"><br/>Additional Requirements</strong>: <ul data-end="1262" data-start="1045"> <li data-end="1125" data-start="1045">International students must meet the Student Visa (Subclass 500) requirements.</li> <li data-end="1262" data-start="1126">For packaged courses, students must successfully complete the lower-level qualification to progress to the higher-level qualification.</li> </ul><p></p> </div>',
    apply_form = 'https://wsc.nsw.edu.au/courses/civil-construction-design-and-painting/cpc30620-certificate-iii-in-painting-and-decorating/',
    updated_at = NOW()
WHERE cricos_course_code = '119988G';
UPDATE courses SET
    course_description = '<div aria-labelledby="course-overview-tab" class="tab-pane fade show active d-block" id="course-overview" role="tabpanel"> <p>This qualification reflects the role of an individual working as a senior civil works designer or a para-professional designer, who supports professional engineers. They perform tasks that are broad, specialised, complex and technical and include strategic areas and initiating activities. They are responsible for the design of complex projects to ensure the implementation of the client’s site requirements and are required to demonstrate self-directed application of theoretical and technical knowledge and initiate solutions to technical problems or management requirements.</p> <strong>Target Groups:<br/></strong> <ul> <li>Individuals seeking to pursue higher education qualifications.</li> <li>Individuals seeking to pursue a career in Civil Construction design.</li> </ul> <p><br/><strong>Career Outcome:<br/></strong></p> <ul> <li>Civil Engineering Draftsperson.</li> <li>Civil Engineering Technician.</li> <li>Road Design Draftsperson.</li> <li>Site Manager.</li> <li>Estimator</li> <li>Contract Administrator</li> </ul> <p><br/><strong>Future Pathways:<br/></strong>Students who complete this course may wish to continue their education into a range of higher level qualifications.</p> <div class="vc_tta-panel" data-vc-content=".vc_tta-panel-body" id="1549253710023-318ff737-b583af1d-f919"> </div> <p><br/><strong><br/></strong></p> </div>',
    total_course_duration = 'Up to 104 Weeks',
    offshore_tuition_fee = 30000,
    enrolment_fee = 250,
    materials_fee = 2450,
    entry_requirements = '<div class="details-description"> <p><strong data-end="207" data-start="188">Age Requirement</strong>: </p><ul data-end="286" data-start="209"> <li data-end="286" data-start="209">Applicants must be at least 18 years old at the commencement of the course.</li> </ul> <strong data-end="315" data-start="288"><br/>Academic Qualifications</strong>: <ul data-end="487" data-start="317"> <li data-end="383" data-start="317">Completion of Australian Year 12 or an equivalent qualification.</li> <li data-end="487" data-start="384">For certain courses, completion of an AQF Diploma or a relevant qualification may be required.</li> </ul> <strong data-end="521" data-start="489"><br/>English Language Proficiency</strong>: <ul data-end="1014" data-start="523"> <li data-end="671" data-start="523">An overall valid academic IELTS score of at least 6.0, with no band less than 5.5, or an equivalent score from a recognized English language test.</li> <li data-end="1014" data-start="672">Alternatively, proficiency can be demonstrated by: <ul data-end="1014" data-start="727"> <li data-end="809" data-start="727">Completion of an Advanced level English course from an approved ELICOS provider.</li> <li data-end="940" data-start="812">Completion of a Certificate IV level course in an Australian Registered Training Organization (RTO) within the last two years.</li> <li data-end="1014" data-start="943">Successfully passing Western Sydney College’s English Placement Test.</li> </ul> </li> </ul> <strong data-end="1043" data-start="1016"><br/>Additional Requirements</strong>: <ul data-end="1262" data-start="1045"> <li data-end="1125" data-start="1045">International students must meet the Student Visa (Subclass 500) requirements.</li> <li data-end="1262" data-start="1126">For packaged courses, students must successfully complete the lower-level qualification to progress to the higher-level qualification.</li> </ul><p></p> </div>',
    apply_form = 'https://wsc.nsw.edu.au/courses/civil-construction-design-and-painting/rii60520-advanced-diploma-of-civil-construction-design/',
    updated_at = NOW()
WHERE cricos_course_code = '114409E';
UPDATE courses SET
    course_description = '<div aria-labelledby="course-overview-tab" class="tab-pane fade show active d-block" id="course-overview" role="tabpanel"> <p>This qualification reflects the role of community services workers involved in the delivery, management and coordination of person-centred services to individuals, groups, and communities.</p> <strong>Target Groups:<br/><br/></strong> <ul> <li>Individuals seeking to pursue a career in a Community Services Industry</li> <li>Individuals seeking to enhance their current skills</li> <li>Individuals seeking to pursue a higher education qualification</li> </ul> <p><br/><strong>Career Outcome:<br/></strong></p> <ul> <li>Community Care Manager,</li> <li>Coordinator of Volunteer Work</li> <li>Team Leader</li> <li>Family Services Coordinator</li> <li>Support Facilitator in Community Services</li> <li>Community Service Worker</li> <li>Community Development Worker</li> <li>Program Coordinator</li> <li>Youth Support Worker</li> </ul> <p><br/><strong>Future Pathways:<br/></strong>Students who complete this course may wish to continue their education into the CHC62015 Advanced Diploma of Community Sector Management or higher education qualifications in community services management.</p> <div class="vc_tta-panel" data-vc-content=".vc_tta-panel-body" id="1549253710023-318ff737-b583af1d-f919"> </div> <p><br/><strong><br/></strong></p> </div>',
