UPDATE courses SET
    course_description = '<div aria-labelledby="course-overview-tab" class="tab-pane fade show active d-block" id="course-overview" role="tabpanel"> <p><span style="color: rgb(0, 0, 0);">This qualification reflects the role of workers who are middle managers or managers across a range of community sector organisations. These people work independently and report to executive management, directors or boards of management. They undertake a range of functions requiring the application of knowledge and skills to achieve results in line with the organisation''s goals and strategic directions. At this level, workers have responsibility for planning and monitoring service delivery, recruitment and performance management of other paid or unpaid workers, managing risk and contributing to continuous improvement within the scope of their specific role. This may include management of a specific programs or project, or broader management of a community-based organisation, early childhood education service, not-for-profit organisation or community centre.</span></p><p><br/></p><p>Target Groups:</p><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><span style="color: rgb(0, 0, 0);">Individuals seeking to pursue a career in a Community Services Industry </span></li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><span style="color: rgb(0, 0, 0);">Individuals seeking to enhance their current skills </span></li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><span style="color: rgb(0, 0, 0);">Individuals seeking to pursue a higher education qualification</span></li></ol><p><br/></p><p>Career Outcomes:</p><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><span style="color: rgb(0, 0, 0);">Centre Manager in Community Services Sector </span></li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><span style="color: rgb(0, 0, 0);">Community Development Worker </span></li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><span style="color: rgb(0, 0, 0);">Neighbourhood Centre Manager </span></li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><span style="color: rgb(0, 0, 0);">Project Manager (Community Services) </span></li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><span style="color: rgb(0, 0, 0);">Program Coordinator</span></li></ol><p><br/></p><p>Future Pathways</p><p><span style="color: rgb(0, 0, 0);">Students who complete this course may wish to continue their education into the higher education qualifications in community services management.</span></p> </div>',
    total_course_duration = 'Up to 78 Weeks',
    offshore_tuition_fee = 24000,
    enrolment_fee = 250,
    materials_fee = 2000,
