    course_description = '<div aria-labelledby="course-overview-tab" class="tab-pane fade show active d-block" id="course-overview" role="tabpanel"> <p>This qualification reflects the role of commercial cooks who use a wide range of well-developed cookery skills and sound knowledge of kitchen operations to prepare food and menu items. Using discretion and judgement, they work with some independence and under limited supervision using plans, policies, and procedures to guide work activities.</p><p> </p><p><strong>Target Groups:</strong></p><p> </p><p><br/></p><p> </p><p><strong>Career Outcome:</strong>This qualification provides a pathway to work in organisations such as restaurants, hotels, clubs, pubs, cafes and coffee shops, or to run a small business in these sectors.<strong>Future Pathways:</strong>Students who complete this course may pursue SIT50422 Diploma of Hospitality Management or higher education<strong><br/></strong></p> </div>',
