UPDATE courses SET
    course_description = '<div aria-labelledby="course-overview-tab" class="tab-pane fade show active d-block" id="course-overview" role="tabpanel"> <p>This qualification reflects the role of highly skilled senior operators who use a broad range of hospitality skills combined with managerial skills and sound knowledge of industry to coordinate hospitality operations. They operate independently, have responsibility for others and make a range of operational business decisions.</p> <p><strong>Target Groups:</strong></p> <p>Target groups for the SIT50422 Diploma of Hospitality Management are individuals who are:</p> <ul> <li> <p>Individuals seeking to pursue a career in a Hospitality Industry</p> </li> <li> <p>Individuals seeking to enhance their current skills</p> </li> <li>Individuals seeking to pursue a higher education qualification</li> </ul> <p><strong><br/>Career Outcome:<br/></strong>This qualification provides a pathway to work in any hospitality industry sector as a departmental or small business manager. The diversity of employers includes restaurants, hotels, motels, catering operations, clubs, pubs, cafés, and coffee shops. This qualification allows for multiskilling and for acquiring targeted skills in accommodation services, cookery, food and beverage and gaming<br/><br/><strong>Future Pathways:<br/></strong>Students who complete this course may pursue SIT60322 Advanced Diploma of Hospitality Management or higher education<br/><br/><strong><br/></strong></p> </div>',
