UPDATE courses SET
    course_description = '<div aria-labelledby="course-overview-tab" class="tab-pane fade show active d-block" id="course-overview" role="tabpanel"> <p class="p1">This qualification reflects the role of individuals who apply knowledge, practical skills, and experience in leadership and management across a range of enterprise and industry contexts.</p> <p class="p1">Individuals at this level display initiative and judgement in planning, organising, implementing, and monitoring their workload and the workload of others. They use communication skills to support individuals and teams to meet organisational or enterprise requirements.</p> <p class="p1">They plan, design, apply and evaluate solutions to unpredictable problems, and identify, analyse and synthesise information from a variety of sources.</p> <div> </div> <strong>Target Groups:<br/></strong> <ul> <li class="p1">Individuals seeking to pursue higher education qualifications.</li> <li class="p1">Individuals seeking to pursue a career as a Manager or Supervisor.</li> <li class="p1">Individuals holding other business qualifications or business experience seeking to gain additional business management and leadership skills.</li> </ul> <p><strong><br/>Career Outcome:<br/></strong>Human Resources Manager, Sales Team Manager, Business Manager</p> <p><strong>Future Pathways:<br/></strong>Students who complete this course may pursue BSB60420-Advanced Diploma of Leadership and Management or higher education qualifications in business or management.</p> <div class="vc_tta-panel" data-vc-content=".vc_tta-panel-body" id="1549382582673-d0625f1e-842e"> </div> </div>',
